import{_ as l,o as i,c as t,a5 as e}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"第2章 論理回路・CPU・命令","description":"","frontmatter":{"title":"第2章 論理回路・CPU・命令","study":{"source":"IT教本","status":"outline","summary":"論理回路からレジスタ、命令の実行へ進むための学習計画・概要です。回路や命令セットの概説を足場に、実際のコードとの対応を観察します。論理回路・CPU設計を順に説明する専用本文は未整備です。\\n\\n## 関連する辞典本文・実践\\n\\n- [関数呼び出し・レジスタ・呼出規約](/runtime/cpp-i","section":"learning","format":"path","domain":"hardware","collection":"low-level","order":3}},"headers":[],"relativePath":"guide/low-level/electricity-cpu-instructions.md","filePath":"guide/low-level/electricity-cpu-instructions.md"}'),n={name:"guide/low-level/electricity-cpu-instructions.md"};function r(s,a,o,d,c,h){return i(),t("div",null,[...a[0]||(a[0]=[e(`<div id="第2章-電気・cpu・命令-──-機械はどうやって「計算」するのか" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="第2章-論理回路・cpu・命令" tabindex="-1">第2章 論理回路・CPU・命令 <a class="header-anchor" href="#第2章-論理回路・cpu・命令" aria-label="Permalink to &quot;第2章 論理回路・CPU・命令&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>論理回路からレジスタ、命令の実行へ進むための<strong>学習計画・概要</strong>です。回路や命令セットの概説を足場に、実際のコードとの対応を観察します。論理回路・CPU設計を順に説明する専用本文は未整備です。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し・レジスタ・呼出規約</a>で、命令を読む際の具体例を確認できます。</li><li><a href="/study/runtime/cpp-internals/cache-branch-simd.html">キャッシュ・分岐予測・SIMD</a>では、命令実行と性能の関係を扱います。</li></ul><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>ゲームループの1周は、CPUが<strong>命令列</strong>を実行することで実現される。 「CPUは命令をメモリから取ってきて解読して実行する機械」という実感がないと、 アセンブリ(第4章)は記号の暗記になり、最適化(第18章)は迷信になる。 また「分岐が重い」「16ms以内に終わらせる」といった現場の会話は、 CPUの動作モデルを持っていて初めて意味が分かる。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>トランジスタ→論理ゲート→加算器→ALU という積み上げを概念的に説明できる</li><li>CPUの基本サイクル(フェッチ→デコード→実行)を説明できる</li><li>レジスタ・プログラムカウンタ・命令セット(ISA)とは何かを説明できる</li><li>クロック周波数・IPCと「処理が16.6msに収まるか」の関係を説明できる</li><li>分岐予測・パイプラインの存在を知り、なぜ分岐ミスが高価か説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第1章(2進数・ビット)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>電気から論理へ(深入りしない)</strong><ul><li>トランジスタ=電気で制御するスイッチ。これだけでよい(半導体物理は不要)</li><li>NANDゲートから AND/OR/NOT/XOR が作れる</li><li>組み合わせ回路: 半加算器→全加算器→nビット加算器→ALU</li><li>順序回路: フリップフロップ=1bit記憶 → レジスタ、クロック=拍</li></ul></li><li><strong>CPUの構造</strong><ul><li>レジスタファイル、ALU、制御ユニット、プログラムカウンタ(PC/RIP)</li><li>フェッチ→デコード→実行→(メモリアクセス)→書き戻し のサイクル</li><li>命令セットアーキテクチャ(ISA)= ハードとソフトの契約書 <ul><li>x86-64(PC/Xbox/PS5)と ARM64(Switch/スマホ/Apple)の2大勢力</li><li>CISCとRISCの思想の違い(現代では内部的に収斂している)</li></ul></li></ul></li><li><strong>命令とは何か</strong><ul><li>機械語命令 = 「操作コード + オペランド」のビット列</li><li>転送(mov)、演算(add/mul)、分岐(jmp/je)、コール(call/ret)の4分類で ほぼ全てのプログラムができている</li><li>条件分岐 = フラグレジスタ + 条件ジャンプ(if文の正体)</li></ul></li><li><strong>性能の基礎モデル</strong><ul><li>1コアのCPU実行時間のモデル: 命令数 × 平均CPI ÷ クロック周波数。 命令の並列実行や待ちの影響は平均CPIに表れる。実際の経過時間にはOSの待機等も関わる</li><li>60fps = 約16.67ms/フレーム。1コアが3GHzで動き続けると仮定すると 約5000万クロック/フレーム。ゲームがその全てを使えるという保証ではない</li><li>現代CPUの高速化(概要のみ、詳細は発展編): パイプライン、スーパースカラ、アウトオブオーダー実行、分岐予測</li><li>分岐予測ミスは命令のやり直しを生む。損失はCPU・コード・周辺の待ちに依存する。 15〜20サイクル等の値は特定条件の目安であり、全CPU共通の定数ではない</li></ul></li><li><strong>(演習)Nand2Tetrisで16bit CPUを自作する</strong><ul><li>NANDゲートだけから始めてCPUとアセンブラを作る。この教本で 唯一の「回路づくり」。1〜6章のハードウェア部だけでOK</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>ストアドプログラム方式</strong>: 命令はメモリ上のただのデータ。 だからコンパイラ(データとして機械語を出力するプログラム)が成立する</li><li><strong>ISAは契約</strong>: 同じx86-64バイナリがIntelでもAMDでも動く理由</li><li><strong>実行時間には予算がある</strong>: 目標フレーム時間と動作周波数を仮定して見積もり、実測する。 ゲームプログラミングは常にこの予算内でのやりくり</li><li><strong>CPUは推測で走る</strong>: 分岐予測・投機実行。「素直なコードは速い」の根拠</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>「この処理、1フレームに収まる?」</td><td>サイクル予算の感覚</td></tr><tr><td>ホットループでの仮想関数/分岐が重い</td><td>分岐予測ミスのコスト</td></tr><tr><td>PC/PS5とSwitchでビルドを分ける</td><td>ISAの違い(x64 vs ARM64)</td></tr><tr><td>「CPUバウンド」という言葉</td><td>CPUの実行モデル</td></tr><tr><td>インライン展開・ループ展開が効く</td><td>命令数とパイプラインの関係</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li><strong>Nand2Tetris プロジェクト1〜5</strong> を完走せよ(HDLでALUとCPUを作る)。 これがこの章のメイン演習。約20〜40時間。</li><li>3GHzのCPUで60fpsのゲームを動かすとき、1フレームあたりのサイクル数を 計算せよ。1命令1サイクルと仮定したら何命令実行できるか。</li><li>C++で「ソート済み配列」と「ランダム配列」それぞれに対し <code>if (a[i] &gt; 128) sum += a[i];</code> のループを計測し、速度差を確認せよ (有名な分岐予測実験)。差の理由を説明せよ。</li><li>電卓アプリを使わずに、<code>x * 10</code> をシフトと加算だけで計算する式を書け (コンパイラが実際にやる最適化)。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『コンピュータシステムの理論と実装(Nand2Tetris)』── この章の主教材</li><li>『CPUの創りかた』── リレー気分で読める和書の名著(読み物として)</li><li>『コンピュータの構成と設計(パタヘネ)』上巻 ── 詳しく知りたくなったら。 全部読む必要はない(1〜4章で十分)</li><li>『プロセッサを支える技術』Hisa Ando ── 現代CPUの高速化技術の和書</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li>nand2tetris 公式ツール群(シミュレータ)</li><li>[godbolt.org (Compiler Explorer)] ── C++→命令列を今日から眺め始める</li><li>余力があれば: RISC-Vの小さなエミュレータ実装(例: GitHubで &quot;riscv emulator c&quot; 検索、1000行程度のものを眺める)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li><strong>Ben Eater: Build an 8-bit computer from scratch</strong> (YouTube) ── ブレッドボードでCPUを組む伝説のシリーズ。全部見なくても フェッチ/デコード/実行の回が神</li><li>Nand2Tetris公式Coursera講義</li><li>CEDEC/GDCの「コンソール向け最適化」系講演(分岐・キャッシュの話が頻出)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>自分がNand2Tetrisで書いたCPU.hdl(自作こそ最高の教材)</li><li>Compiler Explorerで <code>int add(int a,int b){return a+b;}</code> のx64出力 (mov/add/retの3命令であることを確認)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>CPUの基本サイクル(フェッチ→デコード→実行)を、PC(命令ポインタ)の 役割を含めて説明せよ。</li><li>「if文」はCPUレベルでは何になるか? なぜ予測ミスが遅いのか?</li><li>ISAとは何か。x86-64とARM64のバイナリに互換性がないのはなぜか?</li><li>3GHz・IPC=4のCPUは、16.6msで理論上何命令実行できるか?</li><li>ストアドプログラム方式だからこそ可能になっているツールを2つ挙げよ (例: コンパイラ、JIT、セーブステート付きエミュレータ...)</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ゲームループの1周(約16.67ms): 3GHzの1コアなら約5000万クロックの時間幅</span></span>
<span class="line"><span>┌────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ while (running) {                           │</span></span>
<span class="line"><span>│   入力処理     ← mov/cmp/jne… 命令数は実装次第 │</span></span>
<span class="line"><span>│   ゲーム更新   ← 物理・AI・アニメ等の命令列  │</span></span>
<span class="line"><span>│   描画コマンド ← API呼び出しも結局は命令列    │</span></span>
<span class="line"><span>│ }                                           │</span></span>
<span class="line"><span>└────────────────────────────────────────────┘</span></span>
<span class="line"><span>     ▲ すべての行が「フェッチ→デコード→実行」の積み重ね</span></span>
<span class="line"><span>     ▲ パッド入力の検知もUSBドライバの命令実行(第8章)</span></span>
<span class="line"><span>     ▲ GPUもまた別種の命令を実行するプロセッサ(第11章)</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel 64 and IA-32 Architecture / Optimization manuals</a></li></ul>`,35)])])}const P=l(n,[["render",r]]);export{p as __pageData,P as default};
